         data.alm_flow, data.alm_turbidity_warn];
var worst = 'NONE';
for (var i = 0; i < s.length; i++) {
  if (s[i] === 'CRITICAL') { worst = 'CRITICAL'; break; }
  if (s[i] === 'MAJOR' && worst !== 'CRITICAL') { worst = 'MAJOR'; }
